#!/usr/bin/env python3import osimport sysimport timeimport jsonimport argparseimport subprocessfrom pathlib import Pathtry:    import psutilexcept ImportError:    print("Please install psutil: pip install psutil")    sys.exit(1)CONFIG_PATH = Path.home() / ".carla_gui_config.json"def load_config():    if not CONFIG_PATH.exists():        print(f"Config file not found: {CONFIG_PATH}")        sys.exit(1)    return json.loads(CONFIG_PATH.read_text())def kill_carla_processes():    """Kill any CarlaUE4-Shipping.exe or CarlaUE4.exe processes."""    for proc in psutil.process_iter(["name"]):        name = proc.info["name"]        if name in ("CarlaUE4-Win64-Shipping.exe", "CarlaUE4.exe"):            try:                proc.kill()                print(f"Killed {name} (pid {proc.pid})")            except psutil.NoSuchProcess:                passdef start_carla(executable_path: str):    """Launch CARLA with -RenderOffScreen."""    print(f"Starting CARLA: {executable_path} -RenderOffScreen")    subprocess.Popen(        [executable_path, "-RenderOffScreen"],        creationflags=subprocess.CREATE_NEW_PROCESS_GROUP  # Windows-specific flag    )def run_monitor(python_exe: str, monitor_script: str, folder: str):    """Call your carla_monitor.py with --folder=..."""    # replicate your batch’s PYTHONPATH    env = os.environ.copy()    # adjust this to point at your project root as needed    project_root = Path(__file__).parent.parent.parent.resolve()    env["PYTHONPATH"] = str(project_root)    cmd = [        python_exe,        str(monitor_script),        f"--folder={folder}"    ]    print("Running monitor:", " ".join(cmd))    subprocess.call(cmd, env=env)def main():    parser = argparse.ArgumentParser(description="Start CARLA, run monitor, then cleanup.")    parser.add_argument(        "--input",        help="Folder or file to analyze. Overrides saved config.",        default=None    )    args = parser.parse_args()    cfg = load_config()    carla_exe = cfg.get("carla_executable")    if not carla_exe or not Path(carla_exe).exists():        print(f"CARLA executable not found in config or on disk: {carla_exe}")        sys.exit(1)    # determine input path    input_path = args.input or cfg.get("input_path")    if not input_path:        print("No input path provided (via --input or config).")        sys.exit(1)    # derive where your venv python and monitor script live    # adjust these relative paths based on your project layout    script_dir = Path(__file__).parent    python_exe = script_dir / ".." / ".." / "venv" / "Scripts" / "python.exe"    monitor_script = script_dir / ".." / ".." / "helpers" / "carla_monitor.py"    # Step 1: cleanup any old Carla    kill_carla_processes()    time.sleep(2)    # Step 2: start Carla headless    start_carla(carla_exe)    print("Waiting 20 seconds for CARLA to initialize…")    time.sleep(20)    # Step 3: run your monitor    print(f"Got input: {input_path}")    run_monitor(str(python_exe), monitor_script, input_path)    print("Monitor finished. Waiting 10 s before shutdown…")    time.sleep(10)    # Step 4: cleanup again    kill_carla_processes()    print("All done.")if __name__ == "__main__":    main()